#!/usr/bin/env node
// Phase 254 CURATE-01 verifier.
//
// The curation ledger is generated by SubscriptionManifest (accrue_admin) into the tracked
// accrue_admin/storybook/subscription-curation.json. This module is its fail-closed reader:
//
//   default       regenerate the ledger through mix, compare it to the committed copy as decoded
//                 JSON, then apply every ledger rule against the working tree and git history
//   --write       regenerate the committed ledger through its owner (D-05), then verify it
//   --results P   additionally require every survivor to appear in a rendered Phase 252/253 results
//                 bundle (P is a bundle with browser_result_path, or a render-results file)
//   --results-latest
//                 same, with the newest run under accrue_admin/tmp/phase252/ci-results/
//   --self-test   run every rejection scenario against fixtures, each with a positive control
//
// A check that finds nothing is only evidence after the same check found a seeded positive
// (CLAUDE.md "Agent Working Discipline"); referenceScan and frozenSubjectsAt are proved on
// scratch repositories before their zero results are accepted.

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import { isMainModule } from "./main_module.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

export const LEDGER_PATH = "accrue_admin/storybook/subscription-curation.json";
export const MANIFEST_PATH = "storybook/phase252-manifest.json";
export const SUBSCRIPTION_STORY_PATH = "/components/subscription_detail";
export const RESULT_ROOT_RELATIVE = "accrue_admin/tmp/phase252/ci-results";

const DISPOSITIONS = ["retire", "merge", "retain", "reclassify"];
const REASON_CLASSES = ["stale", "impossible", "duplicate"];
const REACHABILITY_STATES = ["reachable", "historic_supported", "unreachable"];
const SURVIVOR_KINDS = ["manifest_entry", "story"];
const REMOVING = ["retire", "merge"];
const FACT_FIELDS = ["actor", "job", "input_source", "production_renderer", "proof_lane", "composition_tier"];
const CANONICAL_CELLS_PER_STATE = 4; // 2 widths x 2 themes, fixed by the Phase 252 browser contract
const REGISTRY_FIELDS = ["family_count", "entry_count", "specimen_count"];
const REQUIRED_AMENDMENT = "AMD-254-01";
const REQUIRED_AMENDMENT_DECISIONS = ["D-06", "D-14", "D-39", "D-40"];

// Evidence kinds. Mechanical kinds are accepted for the reason class they prove; the rejected
// kinds can never justify a record on their own (D-39).
const MECHANICAL_KIND_FOR_CLASS = Object.freeze({
  duplicate: "fact_expected_equality",
  stale: "replacing_owner",
  impossible: "failing_fixture_invariant",
});
const RETAINING_KINDS = ["retained_primitive_regression", "provider_boundary_negative", "claim_drift"];
const REJECTED_EVIDENCE_KINDS = ["grep_absence", "reference_scan_only", "screenshot_similarity"];

// Test files count as running in a required lane only under these roots and with these names.
const REQUIRED_LANES = Object.freeze([
  { prefix: "accrue_admin/test/", pattern: /_test\.exs$/ },
  { prefix: "accrue/test/", pattern: /_test\.exs$/ },
  { prefix: "accrue_portal/test/", pattern: /_test\.exs$/ },
  { prefix: "scripts/ci/", pattern: /\.test\.mjs$/ },
  { prefix: "scripts/dev/", pattern: /\.test\.mjs$/ },
  { prefix: "accrue_admin/e2e/", pattern: /\.spec\.js$/ },
  { prefix: "accrue_admin/test/js/", pattern: /_test\.mjs$/ },
]);

// Where a retired or merged variation id must no longer appear. Planning artifacts, the
// generated ledger and the generated guide name retired ids on purpose and are not scanned.
export const REFERENCE_SCAN_PATHS = Object.freeze([
  "storybook",
  "dev_support",
  "accrue_admin/storybook",
  "accrue_admin/test",
  "accrue_admin/e2e",
]);
const REFERENCE_SCAN_EXCLUDED = Object.freeze([LEDGER_PATH]);

class CurationError extends Error {
  constructor(message, code = "CURATION_INVALID") {
    super(`Phase 254 curation: ${message}`);
    this.code = code;
  }
}

function fail(message, code) {
  throw new CurationError(message, code);
}

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isNonEmptyString(value) {
  return typeof value === "string" && value.trim() !== "";
}

function sha256(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

export function stableStringify(value) {
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  if (isObject(value)) {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function compareSubjects(left, right) {
  if (left.story_path !== right.story_path) return left.story_path < right.story_path ? -1 : 1;
  if (left.variation_id !== right.variation_id) return left.variation_id < right.variation_id ? -1 : 1;
  return 0;
}

// The digest is over a list-of-lists JSON form so it cannot depend on object key order in
// either language (BEAM map key order is not alphabetical).
export function subjectsSha256(subjects) {
  return sha256(JSON.stringify(subjects.map((subject) => [subject.story_path, subject.variation_id, subject.source_path])));
}

// --- git helpers ---------------------------------------------------------------------------

function git(root, args, options = {}) {
  return spawnSync("git", ["-C", root, ...args], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024, ...options });
}

function showAt(root, commit, repoPath) {
  const result = git(root, ["show", `${commit}:${repoPath}`]);
  if (result.status !== 0) fail(`git show ${commit.slice(0, 12)}:${repoPath} failed: ${(result.stderr || "").trim().split("\n")[0]}`, "CURATION_SOURCE_MISSING");
  return result.stdout;
}

function assertCommitReachable(root, commit) {
  if (!/^[0-9a-f]{40}$/.test(commit || "")) fail("frozen_baseline.source_commit must be a full 40 character commit id", "CURATION_SOURCE_COMMIT_INVALID");
  const result = git(root, ["cat-file", "-e", `${commit}^{commit}`]);
  if (result.status !== 0) {
    fail(
      `source_commit ${commit.slice(0, 12)} is unreachable in this checkout (shallow clone or pruned history); fetch full history before verifying the ledger`,
      "CURATION_SOURCE_COMMIT_UNREACHABLE",
    );
  }
}

// %Variation{ is a struct literal whose first key is id. %VariationGroup{ never matches (the
// brace must follow "Variation" directly) and the form-field maps %{id: :q} / %{ id: :status }
// are not structs, so they can never become subjects.
const VARIATION_STRUCT_ID = /%Variation\{\s*id:\s*:([a-z0-9_]+)/g;

export function storyPathForSource(sourcePath) {
  const match = /^storybook(\/.+)\.story\.exs$/.exec(sourcePath);
  if (!match) fail(`subject source ${sourcePath} is neither a manifest nor a storybook/**.story.exs file`, "CURATION_SOURCE_UNSUPPORTED");
  return match[1];
}

export function extractVariationIds(source) {
  return [...source.matchAll(VARIATION_STRUCT_ID)].map((match) => match[1]);
}

export function frozenSubjectsAt(commit, subjectSources, { root = ROOT } = {}) {
  assertCommitReachable(root, commit);
  if (!Array.isArray(subjectSources) || subjectSources.length === 0) fail("frozen_baseline.subject_sources must be a non-empty list");
  const subjects = [];
  for (const sourcePath of subjectSources) {
    const text = showAt(root, commit, sourcePath);
    if (sourcePath.endsWith(".json")) {
      const manifest = JSON.parse(text);
      for (const entry of manifest.entries || []) {
        if (entry.story_path !== SUBSCRIPTION_STORY_PATH) continue;
        subjects.push({ story_path: entry.story_path, variation_id: entry.variation_id, source_path: sourcePath });
      }
    } else {
      const storyPath = storyPathForSource(sourcePath);
      for (const id of extractVariationIds(text)) subjects.push({ story_path: storyPath, variation_id: id, source_path: sourcePath });
    }
  }
  subjects.sort(compareSubjects);
  return subjects;
}

export function frozenManifestAt(commit, { root = ROOT } = {}) {
  assertCommitReachable(root, commit);
  return JSON.parse(showAt(root, commit, MANIFEST_PATH));
}

function diffSubjects(expected, actual) {
  const key = (subject) => `${subject.story_path}||${subject.variation_id}||${subject.source_path}`;
  const left = new Set(expected.map(key));
  const right = new Set(actual.map(key));
  return {
    added: actual.filter((subject) => !left.has(key(subject))).map(key),
    missing: expected.filter((subject) => !right.has(key(subject))).map(key),
  };
}

// --- reference scan ------------------------------------------------------------------------

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// git grep -F finds candidates; the boundary filter then drops identifiers that merely end in
// the token (UI-E2-populated, my_populated, populated_rows).
//
// With `ref` the scan reads that commit's tree instead of the working tree, which is how a
// context pattern is shown to find something before it is trusted to find nothing.
export function referenceScan(variationId, { root = ROOT, paths = REFERENCE_SCAN_PATHS, excluded = REFERENCE_SCAN_EXCLUDED, ref = null } = {}) {
  if (!/^[a-z0-9_]+$/.test(variationId || "")) fail(`variation id ${JSON.stringify(variationId)} is not a plain identifier`);
  if (ref !== null && !/^[0-9a-f]{40}$/.test(ref)) fail("a reference scan ref must be a full commit id");
  const result = git(root, ["grep", "-n", "-I", "-F", "-e", variationId, ...(ref ? [ref] : []), "--", ...paths]);
  if (result.status === 1) return [];
  if (result.status !== 0) fail(`git grep failed: ${(result.stderr || "").trim().split("\n")[0]}`, "CURATION_SCAN_FAILED");
  const exact = new RegExp(`(?<![A-Za-z0-9_-])${escapeRegex(variationId)}(?![A-Za-z0-9_-])`);
  const hits = [];
  for (const rawLine of result.stdout.split("\n")) {
    const line = ref && rawLine.startsWith(`${ref}:`) ? rawLine.slice(ref.length + 1) : rawLine;
    const match = /^([^:]+):(\d+):(.*)$/.exec(line);
    if (!match) continue;
    const [, file, lineNumber, text] = match;
    if (excluded.includes(file)) continue;
    if (exact.test(text)) hits.push({ path: file, line: Number(lineNumber), text: text.trim().slice(0, 200) });
  }
  return hits;
}

function withScratchRepo(fn) {
  const dir = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), "phase254-curation-"));
  try {
    git(dir, ["init", "-q"]);
    git(dir, ["config", "user.email", "scratch@example.invalid"]);
    git(dir, ["config", "user.name", "scratch"]);
    git(dir, ["config", "commit.gpgsign", "false"]);
    return fn(dir);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

function seed(dir, relativePath, content) {
  const absolute = path.join(dir, relativePath);
  fs.mkdirSync(path.dirname(absolute), { recursive: true });
  fs.writeFileSync(absolute, content);
  git(dir, ["add", relativePath]);
}

function commitAll(dir, message) {
  const result = git(dir, ["commit", "-q", "-m", message]);
  if (result.status !== 0) fail(`scratch commit failed: ${result.stderr}`);
  return git(dir, ["rev-parse", "HEAD"]).stdout.trim();
}

// Proves the scan can find something before any zero result is accepted: a seeded exact token
// must be found and a look-alike prefixed identifier must not be counted.
export function proveReferenceScan() {
  return withScratchRepo((dir) => {
    seed(dir, "storybook/components/seeded.story.exs", "variation(:populated, :populated)\n");
    seed(dir, "accrue_admin/test/lookalike_test.exs", "# UI-E2-populated and my_populated are unrelated ids\n");
    const hits = referenceScan("populated", { root: dir });
    return hits.filter((hit) => hit.path === "storybook/components/seeded.story.exs");
  });
}

// --- context -------------------------------------------------------------------------------

function normalizeContext(input = {}) {
  const root = input.root || ROOT;
  const files = input.files || null;
  const readText = input.readText || ((repoPath) => {
    if (files) {
      if (!Object.prototype.hasOwnProperty.call(files, repoPath)) return null;
      return files[repoPath];
    }
    const absolute = path.join(root, repoPath);
    return fs.existsSync(absolute) && fs.statSync(absolute).isFile() ? fs.readFileSync(absolute, "utf8") : null;
  });
  return {
    root,
    readText,
    manifest: input.manifest || null,
    frozenSubjects: input.frozenSubjects || null,
    frozenManifest: input.frozenManifest || null,
    results: input.results || null,
    scan: input.scan || ((variationId) => referenceScan(variationId, { root })),
    scanProbe: input.scanProbe || proveReferenceScan,
    originEvidence: input.originEvidence || null,
    contextProbe: input.contextProbe || null,
  };
}

// --- ledger rules --------------------------------------------------------------------------

function validateBaseline(baseline) {
  if (!Number.isInteger(baseline.entries) || baseline.entries <= 0) fail("frozen_baseline.entries must be a positive integer");
  const compat = baseline.compatibility_ids;
  if (!Array.isArray(compat) || compat.some((id) => !isNonEmptyString(id)) || new Set(compat).size !== compat.length) {
    fail("frozen_baseline.compatibility_ids must be a unique list of ids");
  }
  if (!isObject(baseline.registry) || REGISTRY_FIELDS.some((field) => !Number.isInteger(baseline.registry[field]) || baseline.registry[field] < 0)) {
    fail(`frozen_baseline.registry must carry integer ${REGISTRY_FIELDS.join(", ")}`);
  }
  if (!/^[0-9a-f]{64}$/.test(baseline.manifest_sha256 || "")) fail("frozen_baseline.manifest_sha256 must be a sha256");
  const kitchen = baseline.kitchen_test_digests;
  if (!isObject(kitchen) || Object.keys(kitchen).length === 0 || Object.values(kitchen).some((digest) => !/^[0-9a-f]{64}$/.test(digest))) {
    fail("frozen_baseline.kitchen_test_digests must map test files to sha256 digests");
  }
  if (!/^[0-9a-f]{40}$/.test(baseline.source_commit || "")) fail("frozen_baseline.source_commit must be a full commit id");
  if (!Array.isArray(baseline.subject_sources) || baseline.subject_sources.length === 0 || baseline.subject_sources.some((source) => !isNonEmptyString(source))) {
    fail("frozen_baseline.subject_sources must be a non-empty list of paths");
  }
  if (!Array.isArray(baseline.subjects) || baseline.subjects.length === 0) fail("frozen_baseline.subjects must enumerate the frozen subjects");
  for (const subject of baseline.subjects) {
    if (!isObject(subject) || ![subject.story_path, subject.variation_id, subject.source_path].every(isNonEmptyString)) {
      fail("every frozen subject needs story_path, variation_id and source_path");
    }
    if (!baseline.subject_sources.includes(subject.source_path)) fail(`frozen subject ${subject.story_path}||${subject.variation_id} names a source outside subject_sources`);
  }
  for (let index = 1; index < baseline.subjects.length; index += 1) {
    if (compareSubjects(baseline.subjects[index - 1], baseline.subjects[index]) >= 0) fail("frozen_baseline.subjects must be sorted by story_path then variation_id without duplicates");
  }
  if (baseline.subjects_sha256 !== subjectsSha256(baseline.subjects)) fail("frozen_baseline.subjects_sha256 does not match the enumerated subjects");
}

function validateAmendments(amendments, context, records = [], baseline = null) {
  if (!Array.isArray(amendments)) fail("amendments must be a list");
  const amendment = amendments.find((candidate) => candidate?.id === REQUIRED_AMENDMENT);
  if (!amendment) fail(`ledger is missing amendment ${REQUIRED_AMENDMENT} (the D-06/D-14 literal 15 versus the D-40 retirement)`);
  for (const decision of REQUIRED_AMENDMENT_DECISIONS) {
    if (!Array.isArray(amendment.decisions) || !amendment.decisions.includes(decision)) fail(`${REQUIRED_AMENDMENT} must reference ${decision}`);
  }
  for (const field of ["original", "amended", "rationale"]) {
    if (!isNonEmptyString(amendment[field])) fail(`${REQUIRED_AMENDMENT} is missing ${field}`);
  }
  if (!isObject(amendment.owner_ack) || !/^\d{4}-\d{2}-\d{2}$/.test(amendment.owner_ack.date || "") || !isNonEmptyString(amendment.owner_ack.status)) {
    fail(`${REQUIRED_AMENDMENT} is missing owner_ack {date, status}`);
  }
  if (!Array.isArray(amendment.evidence) || amendment.evidence.length === 0) fail(`${REQUIRED_AMENDMENT} is missing evidence`);
  for (const item of amendment.evidence) assertMarker(item, `${REQUIRED_AMENDMENT} evidence`, context);
  // A retired compatibility id is exactly what the amendment exists for: its record id must be
  // linked as evidence, or the derived count has no recorded reason.
  const compatibility = new Set(baseline?.compatibility_ids || []);
  for (const record of records) {
    if (REMOVING.includes(record?.disposition) && record.subject?.story_path === SUBSCRIPTION_STORY_PATH && compatibility.has(record.subject?.variation_id)) {
      if (!Array.isArray(amendment.record_ids) || !amendment.record_ids.includes(record.id)) {
        fail(`${REQUIRED_AMENDMENT} must link ${record.id} in record_ids, because that record retires compatibility id ${record.subject.variation_id}`);
      }
    }
  }
}

function assertMarker(item, label, context) {
  if (!isObject(item) || !isNonEmptyString(item.path) || !isNonEmptyString(item.marker)) fail(`${label} needs a path and a literal marker`);
  const text = context.readText(item.path);
  if (text === null) fail(`${label} names a missing file: ${item.path}`);
  if (!text.includes(item.marker)) fail(`${label} marker is not present in ${item.path}`);
}

function subjectKey(subject) {
  return `${subject.story_path}||${subject.variation_id}`;
}

function inFrozenBaseline(subject, baseline) {
  if (subject.variation_id === null) return baseline.subjects.some((frozen) => frozen.story_path === subject.story_path);
  return baseline.subjects.some((frozen) => frozen.story_path === subject.story_path && frozen.variation_id === subject.variation_id);
}

function blocksFromEntry(entry) {
  const fact = {};
  for (const field of FACT_FIELDS) fact[field] = entry[field] ?? null;
  return { fact, expected: entry.expected };
}

function validateReasonEvidence(record, context) {
  const evidence = record.reason_evidence;
  if (!isObject(evidence) || !isNonEmptyString(evidence.kind)) fail(`${record.id} needs reason_evidence with a kind`);
  if (REJECTED_EVIDENCE_KINDS.includes(evidence.kind)) {
    fail(`${record.id} rests on ${evidence.kind} evidence, which cannot justify a curation record (grep absence and screenshot similarity are rejected)`);
  }
  if (REMOVING.includes(record.disposition)) {
    const required = MECHANICAL_KIND_FOR_CLASS[record.reason_class];
    if (evidence.kind !== required) fail(`${record.id} is a ${record.reason_class} ${record.disposition} and needs ${required} evidence, not ${evidence.kind}`);
  } else if (!RETAINING_KINDS.includes(evidence.kind) && !Object.values(MECHANICAL_KIND_FOR_CLASS).includes(evidence.kind)) {
    fail(`${record.id} has unknown reason_evidence kind ${evidence.kind}`);
  }
  if (evidence.kind === "replacing_owner") assertMarker(evidence, `${record.id} replacing owner`, context);
  if (evidence.kind === "failing_fixture_invariant") validateTestRef(evidence.test_ref, `${record.id} failing fixture invariant`, context);
}

function validateDuplicateEvidence(record, context) {
  const duplicate = record.duplicate_evidence;
  if (!isObject(duplicate) || !isObject(duplicate.subject) || !isObject(duplicate.survivor)) {
    fail(`${record.id} is a duplicate and needs duplicate_evidence {subject, survivor} with fact and expected blocks`);
  }
  for (const side of ["subject", "survivor"]) {
    if (!isObject(duplicate[side].fact) || !isObject(duplicate[side].expected) || Object.keys(duplicate[side].fact).length === 0 || Object.keys(duplicate[side].expected).length === 0) {
      fail(`${record.id} duplicate_evidence.${side} needs non-empty fact and expected blocks`);
    }
  }
  // Two subjects are a duplicate only when their blocks are exactly equal; any differing field keeps both.
  for (const block of ["fact", "expected"]) {
    if (stableStringify(duplicate.subject[block]) !== stableStringify(duplicate.survivor[block])) {
      fail(`${record.id} claims a duplicate but the ${block} blocks differ; near-equality never merges, keep both subjects`);
    }
  }
  if (context.frozenManifest && record.survivor?.kind === "manifest_entry" && record.subject.variation_id !== null) {
    const byKey = new Map(context.frozenManifest.entries.map((entry) => [entry.key, entry]));
    const subjectEntry = byKey.get(`${record.subject.story_path}||${record.subject.variation_id}`);
    const survivorEntry = byKey.get(record.survivor.key);
    if (!subjectEntry || !survivorEntry) fail(`${record.id} duplicate evidence names an entry absent from the frozen manifest`);
    for (const [side, entry] of [["subject", subjectEntry], ["survivor", survivorEntry]]) {
      const derived = blocksFromEntry(entry);
      if (stableStringify(duplicate[side].fact) !== stableStringify(derived.fact) || stableStringify(duplicate[side].expected) !== stableStringify(derived.expected)) {
        fail(`${record.id} duplicate_evidence.${side} does not match the frozen manifest entry`);
      }
    }
  }
  if (context.originEvidence) context.originEvidence(record);
}

// Commit-anchored duplicate evidence (D-39, 254-06). The subject and survivor blocks are re-derived
// from the manifest as it was at provenance.origin_commit, compared with each other and with the
// blocks the ledger carries, and the fact source must have delegated the subject scenario to the
// survivor scenario at that same commit. A commit where the blocks differ therefore fails.
export function duplicateEvidenceAtCommit(record, { root = ROOT } = {}) {
  const commit = record?.provenance?.origin_commit;
  assertCommitReachable(root, commit);
  const duplicate = record.duplicate_evidence;
  if (!isObject(duplicate) || !isObject(duplicate.subject) || !isObject(duplicate.survivor)) {
    fail(`${record.id} needs duplicate_evidence {subject, survivor} to be checked at ${commit.slice(0, 12)}`);
  }
  if (record.shape_evidence !== undefined) return shapeEvidenceAtCommit(record, commit, root);
  if (record.survivor?.kind !== "manifest_entry" || !isNonEmptyString(record.subject?.variation_id)) {
    fail(`${record.id} duplicate evidence at a commit needs a manifest subject and a manifest_entry survivor`);
  }
  const manifest = JSON.parse(showAt(root, commit, MANIFEST_PATH));
  const byKey = new Map(manifest.entries.map((entry) => [entry.key, entry]));
  const subjectEntry = byKey.get(`${record.subject.story_path}||${record.subject.variation_id}`);
  const survivorEntry = byKey.get(record.survivor.key);
  if (!subjectEntry || !survivorEntry) fail(`${record.id} duplicate evidence names an entry absent from the manifest at ${commit.slice(0, 12)}`);
  const subjectBlocks = blocksFromEntry(subjectEntry);
  const survivorBlocks = blocksFromEntry(survivorEntry);
  for (const block of ["fact", "expected"]) {
    if (stableStringify(subjectBlocks[block]) !== stableStringify(survivorBlocks[block])) {
      fail(`${record.id} claims a duplicate but the ${block} blocks differ at ${commit.slice(0, 12)}: ${record.subject.variation_id} versus ${survivorEntry.variation_id}`);
    }
  }
  for (const [side, blocks] of [["subject", subjectBlocks], ["survivor", survivorBlocks]]) {
    if (stableStringify(duplicate[side]) !== stableStringify(blocks)) {
      fail(`${record.id} duplicate_evidence.${side} does not match the manifest entry at ${commit.slice(0, 12)}`);
    }
  }
  const alias = record.alias_evidence;
  if (alias !== undefined) {
    if (!isObject(alias) || ![alias.facts_path, alias.subject_scenario, alias.survivor_scenario].every(isNonEmptyString)) {
      fail(`${record.id} alias_evidence needs facts_path, subject_scenario and survivor_scenario`);
    }
    if (![alias.subject_scenario, alias.survivor_scenario].every((name) => /^[a-z0-9_]+$/.test(name))) fail(`${record.id} alias_evidence scenarios must be plain identifiers`);
    const facts = showAt(root, commit, alias.facts_path);
    const delegation = new RegExp(`def\\s+fetch!\\(:${alias.subject_scenario}\\),\\s*do:\\s*fetch!\\(:${alias.survivor_scenario}\\)`);
    if (!delegation.test(facts)) fail(`${record.id} fetch!(:${alias.subject_scenario}) did not delegate to fetch!(:${alias.survivor_scenario}) in ${alias.facts_path} at ${commit.slice(0, 12)}`);
  }
  return { commit, subject: subjectEntry.key, survivor: survivorEntry.key, alias: alias !== undefined };
}

// --- action-menu group shape (story-source duplicates) -------------------------------------------

// The shape of an action-menu story variation is mechanical: its story state, then for each group in
// the groups function it renders the group label and the sorted unique kinds of its items (danger
// or standard). Item count, descriptions and values are deliberately not part of the shape.
export function actionMenuShape(source, variationId, groupsFunction) {
  if (!/^[a-z0-9_]+$/.test(variationId || "") || !/^[a-z0-9_]+$/.test(groupsFunction || "")) fail("action-menu shape needs plain identifiers");
  const start = source.search(new RegExp(`\\bid:\\s*:${variationId}\\b`));
  if (start === -1) return null;
  const rest = source.slice(start);
  const next = rest.slice(1).search(/%Variation\{/);
  const block = next === -1 ? rest : rest.slice(0, next + 1);
  const state = /\bstate:\s*:([a-z0-9_]+)/.exec(block);
  const groupsCall = new RegExp(`\\bgroups:\\s*${groupsFunction}\\(\\)`).test(block);
  if (!state || !groupsCall) fail(`variation ${variationId} does not declare a state and groups: ${groupsFunction}()`);
  const body = functionBody(source, groupsFunction);
  if (body === null) fail(`groups function ${groupsFunction} is absent from the story source`);
  const groups = body.split(/%\{\s*label:\s*/).slice(1).map((segment) => {
    const label = /^"([^"]*)"/.exec(segment);
    if (!label) fail(`a group in ${groupsFunction} has no literal label`);
    const items = segment.split(/\baction_item\(/).slice(1);
    if (items.length === 0) fail(`group ${label[1]} in ${groupsFunction} has no items`);
    const kinds = [...new Set(items.map((item) => (/danger\?:\s*true/.test(item.split(/\baction_item\(/)[0]) ? "danger" : "standard")))].sort();
    return { label: label[1], item_kinds: kinds };
  });
  if (groups.length === 0) fail(`${groupsFunction} declares no groups`);
  return { fact: { story_state: state[1] }, expected: { group_shape: groups } };
}

function functionBody(source, name) {
  const start = source.search(new RegExp(`\\n\\s*defp?\\s+${name}\\b`));
  if (start === -1) return null;
  const rest = source.slice(start + 1);
  const next = rest.slice(1).search(/\n  defp? /);
  return next === -1 ? rest : rest.slice(0, next + 1);
}

function shapeEvidenceAtCommit(record, commit, root) {
  const evidence = record.shape_evidence;
  const duplicate = record.duplicate_evidence;
  if (!isObject(evidence) || !isNonEmptyString(evidence.path) || !isObject(evidence.subject) || !isObject(evidence.survivor)) {
    fail(`${record.id} shape_evidence needs path, subject and survivor {variation_id, groups}`);
  }
  for (const side of ["subject", "survivor"]) {
    if (![evidence[side].variation_id, evidence[side].groups].every(isNonEmptyString)) fail(`${record.id} shape_evidence.${side} needs variation_id and groups`);
  }
  if (record.subject?.variation_id !== evidence.subject.variation_id) fail(`${record.id} shape_evidence.subject names a different variation than the record subject`);
  if (record.survivor?.kind !== "story" || record.survivor.variation_id !== evidence.survivor.variation_id) fail(`${record.id} shape_evidence.survivor must name the story survivor variation`);
  const original = showAt(root, commit, evidence.path);
  const subjectShape = actionMenuShape(original, evidence.subject.variation_id, evidence.subject.groups);
  const survivorShape = actionMenuShape(original, evidence.survivor.variation_id, evidence.survivor.groups);
  if (!subjectShape) fail(`${record.id} subject variation ${evidence.subject.variation_id} is absent from ${evidence.path} at ${commit.slice(0, 12)}`);
  if (!survivorShape) fail(`${record.id} survivor variation ${evidence.survivor.variation_id} is absent from ${evidence.path} at ${commit.slice(0, 12)}`);
  for (const block of ["fact", "expected"]) {
    if (stableStringify(subjectShape[block]) !== stableStringify(survivorShape[block])) {
      fail(`${record.id} claims a duplicate but the ${block} shape differs at ${commit.slice(0, 12)}: ${stableStringify(subjectShape[block])} versus ${stableStringify(survivorShape[block])}`);
    }
  }
  for (const [side, shape] of [["subject", subjectShape], ["survivor", survivorShape]]) {
    if (stableStringify(duplicate[side]) !== stableStringify(shape)) fail(`${record.id} duplicate_evidence.${side} does not match the story shape at ${commit.slice(0, 12)}`);
  }
  // The survivor must still render that shape now, and the subject must be gone from the story.
  const currentPath = path.join(root, evidence.path);
  if (!fs.existsSync(currentPath)) fail(`${record.id} story source ${evidence.path} is missing from the tree`);
  const current = fs.readFileSync(currentPath, "utf8");
  const currentSurvivor = actionMenuShape(current, evidence.survivor.variation_id, evidence.survivor.groups);
  if (!currentSurvivor || stableStringify(currentSurvivor) !== stableStringify(duplicate.survivor)) {
    fail(`${record.id} survivor ${evidence.survivor.variation_id} no longer has the pinned shape in the current ${evidence.path}`);
  }
  if (actionMenuShape(current, evidence.subject.variation_id, evidence.subject.groups) !== null || functionBody(current, evidence.subject.groups) !== null) {
    fail(`${record.id} subject ${evidence.subject.variation_id} or its ${evidence.subject.groups} helper is still in the current ${evidence.path}`);
  }
  return { commit, subject: evidence.subject.variation_id, survivor: evidence.survivor.variation_id, shape: true };
}

function compileContexts(record) {
  const contexts = record.reference_scan?.contexts;
  if (contexts === undefined) return [];
  if (!Array.isArray(contexts) || contexts.length === 0 || contexts.some((pattern) => !isNonEmptyString(pattern))) {
    fail(`${record.id} reference_scan.contexts must be a non-empty list of patterns`);
  }
  return contexts.map((pattern) => {
    try {
      return { pattern, regex: new RegExp(pattern) };
    } catch (error) {
      return fail(`${record.id} reference_scan context ${JSON.stringify(pattern)} is not a valid pattern: ${error.message}`);
    }
  });
}

// A context pattern that matches nothing cannot be evidence of anything: each one must find at least
// one reference in the tree as it was at origin_commit, before the removal.
function proveContexts(record, contexts, context) {
  for (const { pattern, regex } of contexts) {
    const hits = context.contextProbe ? context.contextProbe(record.subject.variation_id, record.provenance.origin_commit) : null;
    if (hits === null) return;
    if (!hits.some((hit) => regex.test(hit.text))) {
      fail(`${record.id} reference_scan context ${JSON.stringify(pattern)} matches no reference at origin commit ${record.provenance.origin_commit.slice(0, 12)}, so a zero result for it proves nothing`);
    }
  }
}

function validateTestRef(testRef, label, context) {
  if (!isNonEmptyString(testRef) || !testRef.includes("#")) fail(`${label} needs a test_ref of the form <path>#<test name>`);
  const separator = testRef.indexOf("#");
  const filePath = testRef.slice(0, separator);
  const testName = testRef.slice(separator + 1);
  if (!isNonEmptyString(testName)) fail(`${label} test_ref has no test name`);
  const lane = REQUIRED_LANES.find((candidate) => filePath.startsWith(candidate.prefix) && candidate.pattern.test(filePath));
  if (!lane) fail(`${label} regression ${filePath} is not a test file in a required lane`);
  const text = context.readText(filePath);
  if (text === null) fail(`${label} regression file is missing: ${filePath}`);
  if (!text.includes(testName)) fail(`${label} regression "${testName}" does not exist in ${filePath}`);
}

function survivorPresent(record, context) {
  const extras = record.additional_survivors;
  if (extras !== undefined && !Array.isArray(extras)) fail(`${record.id} additional_survivors must be a list`);
  const survivors = [record.survivor, ...(extras || [])];
  survivors.forEach((survivor, index) => {
    const label = index === 0 ? "survivor" : `additional survivor ${survivor?.key}`;
    if (!isObject(survivor) || !SURVIVOR_KINDS.includes(survivor.kind) || !isNonEmptyString(survivor.key)) {
      fail(`${record.id} needs a survivor {kind: ${SURVIVOR_KINDS.join("|")}, key}`);
    }
    if (survivor.kind === "manifest_entry") {
      if (!context.manifest) fail(`${record.id} survivor cannot be checked without the current manifest`);
      if (!context.manifest.entries.some((entry) => entry.key === survivor.key)) fail(`${record.id} ${label} ${survivor.key} is absent from the current manifest`);
      if (context.results) {
        const rendered = renderedKeys(context.results);
        if (!rendered.has(survivor.key)) fail(`${record.id} ${label} ${survivor.key} is absent from the rendered results`);
      }
    } else {
      const storyFile = `storybook${survivor.key}.story.exs`;
      const text = context.readText(storyFile);
      if (text === null) fail(`${record.id} ${label} story ${survivor.key} is absent from the tree (${storyFile})`);
      if (survivor.variation_id !== undefined) {
        if (!/^[a-z0-9_]+$/.test(survivor.variation_id || "")) fail(`${record.id} ${label} variation_id must be a plain identifier`);
        if (!new RegExp(`(?:\\bid:\\s*:|\\bvariation\\(\\s*:)${survivor.variation_id}\\b`).test(text)) {
          fail(`${record.id} ${label} variation ${survivor.variation_id} is absent from ${storyFile}`);
        }
      }
    }
  });
}

export function renderedKeys(results) {
  const rows = Array.isArray(results?.cases) ? results.cases : [];
  const keys = new Set();
  for (const row of rows) {
    if (isNonEmptyString(row?.variation_key)) keys.add(row.variation_key);
    else if (isNonEmptyString(row?.key)) keys.add(row.key.split("::")[0]);
  }
  return keys;
}

function validateRecord(record, baseline, context) {
  if (!isObject(record)) fail("every record must be an object");
  if (!/^CUR-254-\d{2,}$/.test(record.id || "")) fail(`record id ${JSON.stringify(record.id)} must match CUR-254-NN`);
  const subject = record.subject;
  if (!isObject(subject) || !isNonEmptyString(subject.story_path) || !subject.story_path.startsWith("/")) fail(`${record.id} needs a subject.story_path`);
  if (subject.story_path === "/dev/components" || subject.story_path.startsWith("/dev/components/")) fail(`${record.id} subject ${subject.story_path} is under /dev/components, which curation never touches`);
  if (!(subject.variation_id === null || isNonEmptyString(subject.variation_id))) fail(`${record.id} subject.variation_id must be a string or null`);
  if (!(subject.scenario_id === null || isNonEmptyString(subject.scenario_id))) fail(`${record.id} subject.scenario_id must be a string or null`);
  if (!inFrozenBaseline(subject, baseline)) fail(`${record.id} subject ${subject.story_path}${subject.variation_id ? `||${subject.variation_id}` : ""} is absent from the frozen baseline`);

  if (!DISPOSITIONS.includes(record.disposition)) fail(`${record.id} disposition must be one of ${DISPOSITIONS.join(", ")}`);
  if (REMOVING.includes(record.disposition)) {
    if (!REASON_CLASSES.includes(record.reason_class)) fail(`${record.id} ${record.disposition} needs reason_class ${REASON_CLASSES.join("|")}`);
  } else if (record.reason_class !== null && record.reason_class !== undefined) {
    if (!REASON_CLASSES.includes(record.reason_class)) fail(`${record.id} reason_class must be ${REASON_CLASSES.join("|")} or null`);
    if (record.reason_class === "duplicate") fail(`${record.id} is a ${record.disposition}; reason_class duplicate is reserved for removals`);
  }

  if (record.disposition === "reclassify" && !isNonEmptyString(record.classification)) fail(`${record.id} is a reclassify and needs a classification`);

  const reachability = record.reachability;
  if (!isObject(reachability) || !REACHABILITY_STATES.includes(reachability.state) || !isNonEmptyString(reachability.owner)) {
    fail(`${record.id} needs reachability {state: ${REACHABILITY_STATES.join("|")}, owner, evidence}`);
  }
  if (!Array.isArray(reachability.evidence) || reachability.evidence.length === 0) fail(`${record.id} reachability needs at least one {path, marker} evidence item`);
  for (const item of reachability.evidence) assertMarker(item, `${record.id} reachability evidence`, context);

  if (!isNonEmptyString(record.reason)) fail(`${record.id} needs a reason`);
  validateReasonEvidence(record, context);
  if (REMOVING.includes(record.disposition) && record.reason_class === "duplicate") validateDuplicateEvidence(record, context);

  survivorPresent(record, context);

  if (!Array.isArray(record.preserved_regressions) || record.preserved_regressions.length === 0) fail(`${record.id} needs at least one preserved regression`);
  for (const regression of record.preserved_regressions) {
    if (!isObject(regression) || !isNonEmptyString(regression.protects)) fail(`${record.id} preserved regression needs test_ref and protects`);
    validateTestRef(regression.test_ref, `${record.id} preserved regression`, context);
  }

  if (record.kitchen_impact !== "none") fail(`${record.id} kitchen_impact must be exactly "none"`);
  if (!isObject(record.provenance) || !isNonEmptyString(record.provenance.origin_commit) || !isNonEmptyString(record.provenance.decided_in)) {
    fail(`${record.id} needs provenance {origin_commit, decided_in}`);
  }

  if (REMOVING.includes(record.disposition) && subject.variation_id !== null) {
    if (context.scanProbe().length === 0) fail("the reference scan did not find its seeded positive, so a zero result cannot be accepted");
    const allowed = new Set(record.reference_scan?.allowed_paths || []);
    const contexts = compileContexts(record);
    proveContexts(record, contexts, context);
    let hits = context.scan(subject.variation_id).filter((hit) => !allowed.has(hit.path));
    if (contexts.length > 0) hits = hits.filter((hit) => contexts.some(({ regex }) => regex.test(hit.text)));
    if (hits.length > 0) {
      fail(`${record.id} ${record.disposition} subject ${subject.variation_id} is still referenced at ${hits.slice(0, 3).map((hit) => `${hit.path}:${hit.line}`).join(", ")}`);
    }
  }
}

function validateCounts(ledger, baseline, context) {
  const current = ledger.current;
  if (!isObject(current)) fail("ledger has no current counts block");
  if (!Number.isInteger(current.entries)) fail("current.entries must be an integer");
  if (!Array.isArray(current.compatibility_ids)) fail("current.compatibility_ids must be a list");
  if (!isObject(current.registry) || REGISTRY_FIELDS.some((field) => !Number.isInteger(current.registry[field]))) fail(`current.registry must carry integer ${REGISTRY_FIELDS.join(", ")}`);

  const retired = ledger.records.filter((record) => REMOVING.includes(record.disposition) && record.subject.story_path === SUBSCRIPTION_STORY_PATH && record.subject.variation_id !== null);
  const retiredIds = retired.map((record) => record.subject.variation_id);
  if (new Set(retiredIds).size !== retiredIds.length) fail("a manifest subject is retired by more than one record");

  if (current.entries !== baseline.entries - retired.length) {
    fail(`baseline entries ${baseline.entries} minus ${retired.length} retired does not equal current entries ${current.entries}; retirements need a record and a record needs a retirement`);
  }
  const expectedCompat = baseline.compatibility_ids.filter((id) => !retiredIds.includes(id)).sort();
  if (stableStringify([...current.compatibility_ids].sort()) !== stableStringify(expectedCompat)) {
    fail("current compatibility ids do not equal the baseline minus the retired ids");
  }
  for (const field of REGISTRY_FIELDS) {
    if (current.registry[field] < baseline.registry[field]) fail(`registry ${field} ${current.registry[field]} is below the frozen baseline ${baseline.registry[field]}`);
  }
  if (stableStringify(current.kitchen_test_digests) !== stableStringify(baseline.kitchen_test_digests)) {
    fail("a component-kitchen test digest changed from the frozen baseline (kitchen_impact must stay none)");
  }
  if (context.manifest && context.manifest.entries.length !== current.entries) {
    fail(`ledger current.entries ${current.entries} does not equal the tracked manifest's ${context.manifest.entries.length} entries`);
  }
}

export function verifyLedger(ledger, context = {}) {
  const ctx = normalizeContext(context);
  if (!isObject(ledger)) fail("ledger must be a JSON object");
  if (ledger.schema_version !== 1) fail("unsupported ledger schema_version");
  if (!isObject(ledger.frozen_baseline)) fail("ledger has no frozen_baseline; every ledger must carry the frozen baseline it is checked against");
  const baseline = ledger.frozen_baseline;
  validateBaseline(baseline);
  if (!Array.isArray(ledger.records)) fail("records must be a list");
  if (!isObject(ledger.source_digests) || Object.keys(ledger.source_digests).length === 0) fail("ledger has no source_digests");

  if (!Array.isArray(ledger.records)) fail("records must be a list");
  validateAmendments(ledger.amendments, ctx, ledger.records, baseline);

  const ids = ledger.records.map((record) => record?.id);
  const sorted = [...ids].sort();
  if (new Set(ids).size !== ids.length) fail("record ids must be unique");
  if (JSON.stringify(ids) !== JSON.stringify(sorted)) fail("records must be sorted by id");
  for (const record of ledger.records) validateRecord(record, baseline, ctx);

  validateCounts(ledger, baseline, ctx);

  if (ctx.frozenSubjects) {
    const drift = diffSubjects(ctx.frozenSubjects, baseline.subjects);
    if (drift.added.length || drift.missing.length) {
      fail(`frozen subjects drifted from source_commit ${baseline.source_commit.slice(0, 12)}: added [${drift.added.join(", ")}], missing [${drift.missing.join(", ")}]`);
    }
    if (subjectsSha256(ctx.frozenSubjects) !== baseline.subjects_sha256) fail("frozen_baseline.subjects_sha256 differs from the digest derived at source_commit");
  }
  return { records: ledger.records.length, removed: ledger.records.filter((record) => REMOVING.includes(record.disposition)).length };
}

// --- derived counts ------------------------------------------------------------------------

export function expectedPhase252Cells(ledger) {
  if (!isObject(ledger) || !isObject(ledger.frozen_baseline) || !Array.isArray(ledger.records)) {
    fail("cannot derive Phase 252 cell counts without a ledger that has frozen_baseline and records", "CURATION_LEDGER_UNREADABLE");
  }
  const baseline = ledger.frozen_baseline;
  if (!Number.isInteger(baseline.entries) || !Array.isArray(baseline.compatibility_ids) || baseline.compatibility_ids.length > baseline.entries) {
    fail("frozen_baseline lacks entries and compatibility_ids", "CURATION_LEDGER_UNREADABLE");
  }
  const retired = new Set(
    ledger.records
      .filter((record) => REMOVING.includes(record.disposition) && record.subject?.story_path === SUBSCRIPTION_STORY_PATH && typeof record.subject?.variation_id === "string")
      .map((record) => record.subject.variation_id),
  );
  for (const id of retired) {
    if (!baseline.compatibility_ids.includes(id)) fail(`only compatibility ids may be retired from the Phase 252 browser cells, not ${id}`);
  }
  const canonicalStates = baseline.entries - baseline.compatibility_ids.length;
  const canonical = canonicalStates * CANONICAL_CELLS_PER_STATE;
  const compatibility = baseline.compatibility_ids.filter((id) => !retired.has(id)).length;
  return { canonical, compatibility, total: canonical + compatibility };
}

export function readCurationLedger(root = ROOT) {
  const ledgerPath = path.join(root, LEDGER_PATH);
  let text;
  try {
    text = fs.readFileSync(ledgerPath, "utf8");
  } catch (error) {
    fail(`curation ledger is missing or unreadable at ${LEDGER_PATH} (${error.code || error.message}); counts never default to a smaller number`, "CURATION_LEDGER_UNREADABLE");
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    fail(`curation ledger at ${LEDGER_PATH} is not valid JSON: ${error.message}`, "CURATION_LEDGER_UNREADABLE");
  }
  return null;
}

export function expectedPhase252CellsFromRoot(root = ROOT) {
  return expectedPhase252Cells(readCurationLedger(root));
}

// --- regeneration through the owning module ------------------------------------------------

function regenerationCode(target) {
  if (/["\\#\n]/.test(target)) fail(`refusing a regeneration target with unsafe characters: ${target}`);
  return [
    "{:ok, _started} = Application.ensure_all_started(:localize)",
    `:ok = AccrueAdmin.Storybook.SubscriptionManifest.write_curation!("${target}")`,
  ].join("\n");
}

function runMix(root, target) {
  const result = spawnSync("mix", ["run", "--no-start", "-e", regenerationCode(target)], {
    cwd: path.join(root, "accrue_admin"),
    env: { ...process.env, MIX_ENV: "test" },
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
    timeout: 20 * 60 * 1000,
  });
  if (result.status !== 0) {
    const tail = `${result.stdout || ""}${result.stderr || ""}`.trim().split("\n").slice(-12).join("\n");
    fail(`mix could not regenerate the ledger (exit ${result.status}):\n${tail}`, "CURATION_REGENERATION_FAILED");
  }
}

export function regenerateLedger(root = ROOT) {
  const dir = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), "phase254-curation-regen-"));
  const target = path.join(dir, "subscription-curation.json");
  try {
    runMix(root, target);
    return JSON.parse(fs.readFileSync(target, "utf8"));
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

export function writeLedger(root = ROOT) {
  runMix(root, path.join(root, LEDGER_PATH));
}

function newestResultsFile(root) {
  const base = path.join(root, RESULT_ROOT_RELATIVE);
  if (!fs.existsSync(base)) fail(`no results directory at ${RESULT_ROOT_RELATIVE}`, "CURATION_RESULTS_MISSING");
  const runs = fs.readdirSync(base, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(base, entry.name, "results.json")))
    .map((entry) => ({ file: path.join(base, entry.name, "results.json"), mtime: fs.statSync(path.join(base, entry.name, "results.json")).mtimeMs }))
    .sort((left, right) => right.mtime - left.mtime);
  if (runs.length === 0) fail(`no run with results.json under ${RESULT_ROOT_RELATIVE}`, "CURATION_RESULTS_MISSING");
  return runs[0].file;
}

export function loadRenderResults(resultsPath, root = ROOT) {
  const absolute = path.resolve(root, resultsPath);
  const bundle = JSON.parse(fs.readFileSync(absolute, "utf8"));
  if (isNonEmptyString(bundle.browser_result_path)) {
    return JSON.parse(fs.readFileSync(path.resolve(root, bundle.browser_result_path), "utf8"));
  }
  if (!Array.isArray(bundle.cases)) fail(`results file ${resultsPath} has neither browser_result_path nor cases`, "CURATION_RESULTS_INVALID");
  return bundle;
}

export function verifyCommitted({ root = ROOT, resultsPath = null } = {}) {
  const committed = readCurationLedger(root);
  const regenerated = regenerateLedger(root);
  if (stableStringify(committed) !== stableStringify(regenerated)) {
    fail(`${LEDGER_PATH} is stale; regenerate it with node scripts/ci/verify_phase254_curation.mjs --write`, "CURATION_STALE");
  }
  const manifest = JSON.parse(fs.readFileSync(path.join(root, MANIFEST_PATH), "utf8"));
  const baseline = committed.frozen_baseline;
  const context = {
    root,
    manifest,
    frozenSubjects: frozenSubjectsAt(baseline.source_commit, baseline.subject_sources, { root }),
    frozenManifest: frozenManifestAt(baseline.source_commit, { root }),
    results: resultsPath ? loadRenderResults(resultsPath, root) : null,
    originEvidence: (record) => duplicateEvidenceAtCommit(record, { root }),
    contextProbe: (variationId, commit) => referenceScan(variationId, { root, ref: commit, excluded: [] }),
  };
  return verifyLedger(committed, context);
}

// --- self-test -----------------------------------------------------------------------------

function fixtureWorld() {
  const manifestEntry = (id, expectedExtra = {}) => ({
    key: `${SUBSCRIPTION_STORY_PATH}||${id}`,
    story_path: SUBSCRIPTION_STORY_PATH,
    variation_id: id,
    scenario_id: id,
    actor: "operator",
    job: "inspect",
    input_source: "fixture facts",
    production_renderer: "Renderer.area/1",
    proof_lane: "static render",
    composition_tier: "component",
    expected: { facts: { amount_minor: 100 }, ...expectedExtra },
  });
  const entries = [manifestEntry("active"), manifestEntry("populated"), manifestEntry("braintree_pruned"), manifestEntry("dunning_active")];
  const subjects = [
    { story_path: SUBSCRIPTION_STORY_PATH, variation_id: "active", source_path: MANIFEST_PATH },
    { story_path: SUBSCRIPTION_STORY_PATH, variation_id: "braintree_pruned", source_path: MANIFEST_PATH },
    { story_path: SUBSCRIPTION_STORY_PATH, variation_id: "dunning_active", source_path: MANIFEST_PATH },
    { story_path: SUBSCRIPTION_STORY_PATH, variation_id: "populated", source_path: MANIFEST_PATH },
    { story_path: "/components/detail", variation_id: "read_only", source_path: "storybook/components/detail.story.exs" },
  ];
  subjects.sort(compareSubjects);
  const digest = (label) => sha256(label);
  const files = {
    "storybook/components/detail.story.exs": "%Variation{ id: :read_only }\n",
    "accrue_admin/test/dev/ledger_fixture_test.exs": 'test "keeps the detail primitive" do\n  assert true\nend\ntest "removes populated alias" do\nend\n',
    "accrue_admin/lib/owner.ex": "def summary_list(assigns) do\n",
    "guides/doc_only.md": "# docs\n",
    "accrue_admin/test/dev/replacing_owner_test.exs": "# fixture\n",
  };
  const record = (overrides = {}) => ({
    id: "CUR-254-01",
    subject: { story_path: "/components/detail", variation_id: null, scenario_id: null },
    disposition: "retain",
    reason_class: null,
    reachability: { state: "reachable", owner: "Detail.summary_list/1", evidence: [{ path: "accrue_admin/lib/owner.ex", marker: "def summary_list" }] },
    reason: "only Storybook coverage of summary_list",
    reason_evidence: { kind: "retained_primitive_regression" },
    survivor: { kind: "story", key: "/components/detail" },
    preserved_regressions: [{ test_ref: "accrue_admin/test/dev/ledger_fixture_test.exs#keeps the detail primitive", protects: "summary_list contract" }],
    kitchen_impact: "none",
    provenance: { origin_commit: "a".repeat(40), decided_in: "254-04-01" },
    ...overrides,
  });
  const ledger = {
    schema_version: 1,
    frozen_baseline: {
      source_commit: "a".repeat(40),
      entries: 4,
      compatibility_ids: ["braintree_pruned", "dunning_active", "populated"],
      registry: { family_count: 30, entry_count: 42, specimen_count: 75 },
      manifest_sha256: digest("manifest"),
      kitchen_test_digests: { "accrue_admin/test/dev/kitchen_test.exs": digest("kitchen") },
      subject_sources: [MANIFEST_PATH, "storybook/components/detail.story.exs"],
      subjects,
      subjects_sha256: subjectsSha256(subjects),
    },
    current: {
      entries: 4,
      compatibility_ids: ["braintree_pruned", "dunning_active", "populated"],
      registry: { family_count: 30, entry_count: 42, specimen_count: 75 },
      kitchen_test_digests: { "accrue_admin/test/dev/kitchen_test.exs": digest("kitchen") },
    },
    records: [record()],
    amendments: [
      {
        id: REQUIRED_AMENDMENT,
        decisions: [...REQUIRED_AMENDMENT_DECISIONS],
        original: "15 literal browser cells",
        amended: "15 is the frozen baseline fixture; live counts derive from the ledger",
        rationale: "D-39 derives the pinned counts from the ledger",
        evidence: [{ path: "accrue_admin/lib/owner.ex", marker: "summary_list" }],
        owner_ack: { date: "2026-10-28", status: "owner-accepted at plan time" },
      },
    ],
    source_digests: { "accrue_admin/lib/owner.ex": digest("owner") },
  };
  const context = { files, manifest: { entries }, scan: () => [], scanProbe: () => [{ path: "seeded", line: 1, text: "seeded" }] };
  return { ledger, context, record, entries, files, subjects };
}

function expectRejected(world, mutate, pattern, contextMutate = null) {
  const ledger = clone(world.ledger);
  const context = { ...world.context, files: { ...world.context.files } };
  mutate(ledger, context);
  if (contextMutate) contextMutate(context);
  assert.throws(() => verifyLedger(ledger, context), pattern);
}

// A removal fixture: populated retired as an exact duplicate of active.
function removalWorld() {
  const world = fixtureWorld();
  const [active, populated] = [world.entries[0], world.entries[1]];
  const blocks = (entry) => blocksFromEntry(entry);
  const removal = world.record({
    id: "CUR-254-02",
    subject: { story_path: SUBSCRIPTION_STORY_PATH, variation_id: "populated", scenario_id: "populated" },
    disposition: "retire",
    reason_class: "duplicate",
    reason: "populated resolves to the same facts as active",
    reason_evidence: { kind: "fact_expected_equality" },
    duplicate_evidence: { subject: blocks(populated), survivor: blocks(active) },
    survivor: { kind: "manifest_entry", key: `${SUBSCRIPTION_STORY_PATH}||active` },
    preserved_regressions: [{ test_ref: "accrue_admin/test/dev/ledger_fixture_test.exs#removes populated alias", protects: "active renders the same facts" }],
  });
  world.ledger.records.push(removal);
  world.ledger.amendments[0].record_ids = ["CUR-254-02"];
  world.ledger.current.entries = 3;
  world.ledger.current.compatibility_ids = ["braintree_pruned", "dunning_active"];
  world.context.manifest = { entries: world.entries.filter((entry) => entry.variation_id !== "populated") };
  world.context.frozenManifest = { entries: world.entries };
  return world;
}

function manifestFixtureJson(ids) {
  return JSON.stringify({
    entries: ids.map((id) => ({ key: `${SUBSCRIPTION_STORY_PATH}||${id}`, story_path: SUBSCRIPTION_STORY_PATH, variation_id: id })),
  });
}

